from dispatchiq.helpers import route, route_cost, travel_min

_RC_CACHE = {}


def _rc(state, tech, seq):
    key = (tech["id"], tuple(seq))
    if key in _RC_CACHE:
        return _RC_CACHE[key]
    if not seq:
        _RC_CACHE[key] = 0.0
        return 0.0
    c = route_cost(state, tech, seq)
    val = c if c < 1e6 else float('inf')
    _RC_CACHE[key] = val
    return val


def _tech_by_id(state, tid):
    for t in state["techs"]:
        if t["id"] == tid:
            return t
    return None


def _churn_delta(state, jid, from_id, to_id):
    job = state["jobs"][jid]
    orig = job.get("morning_tech")
    if orig is None:
        return 0.0
    ot = _tech_by_id(state, orig)
    if ot is None or ot["sick"]:
        return 0.0
    d = 0.0
    if from_id is not None and from_id != orig:
        d -= 20
    if to_id is not None and to_id != orig:
        d += 20
    return d


def _drop_low_priority(state, tech, seq, keep=None):
    """Make seq feasible by removing lowest-priority jobs first.
    Returns (kept_seq, dropped_ids) or (None, []) if impossible to keep `keep`."""
    seq = list(seq)
    if _rc(state, tech, seq) < 1e6:
        return seq, []
    dropped = []
    candidates = [j for j in seq if j != keep]

    def sort_key(j):
        job = state["jobs"][j]
        return (job["priority"], -job["duration"], -job["latest"])

    candidates.sort(key=sort_key)
    for j in candidates:
        seq.remove(j)
        dropped.append(j)
        if _rc(state, tech, seq) < 1e6:
            return seq, dropped
    if keep is not None:
        seq_keep = [keep]
        if _rc(state, tech, seq_keep) < 1e6:
            dropped.extend([j for j in seq if j != keep])
            return seq_keep, dropped
        return None, []
    return [], dropped


def _nn_order(state, tech, seq):
    jobs = state["jobs"]
    remaining = list(seq)
    out = []
    cur = tech["loc"]
    while remaining:
        best = None
        bestd = None
        for j in remaining:
            try:
                d = travel_min(state, cur, jobs[j]["loc"])
            except Exception:
                d = 0.0
            if bestd is None or d < bestd:
                bestd = d
                best = j
        out.append(best)
        cur = jobs[best]["loc"]
        remaining.remove(best)
    return out


def _candidate_orders(state, tech, seq):
    if len(seq) <= 1:
        return [list(seq)]
    jobs = state["jobs"]
    cands = [list(seq)]
    cands.append(sorted(seq, key=lambda j: (jobs[j]["latest"], jobs[j]["earliest"])))
    cands.append(sorted(seq, key=lambda j: (jobs[j]["earliest"], jobs[j]["latest"])))
    cands.append(sorted(seq, key=lambda j: (-jobs[j]["priority"], jobs[j]["latest"])))
    cands.append(sorted(seq, key=lambda j: (jobs[j]["latest"] - jobs[j]["duration"], jobs[j]["earliest"])))
    cands.append(_nn_order(state, tech, seq))
    cands.append(list(reversed(seq)))
    return cands


def _best_candidate(state, tech, seq):
    best = None
    best_c = float('inf')
    for cand in _candidate_orders(state, tech, seq):
        c = _rc(state, tech, cand)
        if c < best_c - 1e-9:
            best_c = c
            best = cand
    return best if best is not None else list(seq)


def _two_opt_once(state, tech, seq):
    n = len(seq)
    if n < 3:
        return list(seq)
    cur = list(seq)
    c_cur = _rc(state, tech, cur)
    if c_cur == float('inf'):
        return cur
    for i in range(n - 1):
        for j in range(i + 1, n):
            new = cur[:i] + list(reversed(cur[i:j + 1])) + cur[j + 1:]
            c = _rc(state, tech, new)
            if c < c_cur - 1e-9:
                return new
    return cur


def _or_opt_once(state, tech, seq):
    n = len(seq)
    if n < 2:
        return list(seq)
    cur = list(seq)
    c_cur = _rc(state, tech, cur)
    if c_cur == float('inf'):
        return cur
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            new = cur[:i] + cur[i + 1:]
            new = new[:j] + [cur[i]] + new[j:]
            c = _rc(state, tech, new)
            if c < c_cur - 1e-9:
                return new
    return cur


def _optimize_seq(state, tech, seq, rounds=4):
    if not seq:
        return []
    cur = _best_candidate(state, tech, seq)
    c_cur = _rc(state, tech, cur)
    for _ in range(rounds):
        new = _two_opt_once(state, tech, cur)
        c_new = _rc(state, tech, new)
        if c_new < c_cur - 1e-9:
            cur = new
            c_cur = c_new
        new = _or_opt_once(state, tech, cur)
        c_new = _rc(state, tech, new)
        if c_new < c_cur - 1e-9:
            cur = new
            c_cur = c_new
    return cur


def _try_insert_improved(state, plan, healthy, jid, allow_drop=True):
    """Try to insert jid into any healthy tech, possibly dropping lower priority jobs.
    For emergency jobs, always pick the best feasible insertion (even if costly)."""
    job = state["jobs"][jid]
    p_new = job["priority"]
    is_em = job["emergency"]
    best_delta = float('inf') if is_em else 0.0
    best_move = None

    for t in healthy:
        if job["skill"] not in t["skills"]:
            continue
        seq = plan[t["id"]]
        c_old = _rc(state, t, seq)
        if c_old == float('inf'):
            continue
        for pos in range(len(seq) + 1):
            candidate = seq[:pos] + [jid] + seq[pos:]
            c_cand = _rc(state, t, candidate)
            if c_cand < 1e6:
                # feasible without drops
                delta = c_cand - c_old - 150 * p_new + _churn_delta(state, jid, None, t["id"])
                if delta < best_delta - 1e-9:
                    best_delta = delta
                    best_move = (t["id"], candidate)
                # try dropping one existing job to improve even when feasible
                if allow_drop:
                    for j in candidate:
                        if j == jid:
                            continue
                        p_j = state["jobs"][j]["priority"]
                        if not is_em and p_j > p_new:
                            continue
                        new_cand = [x for x in candidate if x != j]
                        c_drop = _rc(state, t, new_cand)
                        if c_drop < 1e6:
                            d = c_drop - c_old - 150 * p_new + 150 * p_j
                            d += _churn_delta(state, jid, None, t["id"])
                            d += _churn_delta(state, j, t["id"], None)
                            if d < best_delta - 1e-9:
                                best_delta = d
                                best_move = (t["id"], new_cand)
            else:
                # infeasible, try dropping multiple low-priority jobs
                if allow_drop:
                    kept, dropped = _drop_low_priority(state, t, candidate, keep=jid)
                    if kept is not None and jid in kept:
                        c_kept = _rc(state, t, kept)
                        if c_kept < 1e6:
                            d = c_kept - c_old - 150 * p_new
                            for j in dropped:
                                d += 150 * state["jobs"][j]["priority"]
                                d += _churn_delta(state, j, t["id"], None)
                            d += _churn_delta(state, jid, None, t["id"])
                            if d < best_delta - 1e-9:
                                best_delta = d
                                best_move = (t["id"], kept)
    return best_move


def _greedy_initial(state):
    healthy = [t for t in state["techs"] if not t["sick"]]
    plan = {}
    for t in healthy:
        seq = list(t["remaining"])
        if seq:
            r = route(state, t, seq)
            if not r["feasible"]:
                seq, _ = _drop_low_priority(state, t, seq)
                if seq is None:
                    seq = []
        plan[t["id"]] = _optimize_seq(state, t, seq)

    assigned = set()
    for t in healthy:
        assigned.update(plan[t["id"]])
    unassigned = [jid for jid in state["jobs"] if jid not in assigned]
    unassigned.sort(key=lambda jid: (
        not state["jobs"][jid]["emergency"],
        -state["jobs"][jid]["priority"],
        state["jobs"][jid]["release"],
    ))

    for jid in unassigned:
        job = state["jobs"][jid]
        is_em = job["emergency"]
        best = _try_insert_improved(state, plan, healthy, jid, allow_drop=True)
        if best is not None:
            plan[best[0]] = best[1]
        elif is_em:
            # force emergency insertion
            for t in healthy:
                if job["skill"] in t["skills"]:
                    seq = plan[t["id"]]
                    for new_seq in ([jid] + seq, seq + [jid]):
                        kept, _ = _drop_low_priority(state, t, new_seq, keep=jid)
                        if kept is not None and jid in kept:
                            plan[t["id"]] = kept
                            break
                    else:
                        continue
                    break
    return plan


def _local_search(state, plan, max_iters=15):
    healthy = [t for t in state["techs"] if not t["sick"]]
    if not healthy:
        return plan

    for _ in range(max_iters):
        improved = False

        # 1. Re-sequence within each tech (or-opt then 2-opt)
        for t in healthy:
            seq = plan[t["id"]]
            if len(seq) < 2:
                continue
            c_old = _rc(state, t, seq)
            new = _or_opt_once(state, t, seq)
            c_new = _rc(state, t, new)
            if c_new < c_old - 1e-9:
                plan[t["id"]] = new
                improved = True
                continue
            if len(seq) >= 3:
                new = _two_opt_once(state, t, seq)
                c_new = _rc(state, t, new)
                if c_new < c_old - 1e-9:
                    plan[t["id"]] = new
                    improved = True

        # 2. Relocate a job to another tech
        if not improved:
            done = False
            for t1 in healthy:
                if done:
                    break
                seq1 = plan[t1["id"]]
                c1_old = _rc(state, t1, seq1)
                for i in range(len(seq1)):
                    if done:
                        break
                    jid = seq1[i]
                    job = state["jobs"][jid]
                    new_seq1 = seq1[:i] + seq1[i + 1:]
                    c1_new = _rc(state, t1, new_seq1)
                    if c1_new == float('inf'):
                        continue
                    for t2 in healthy:
                        if done:
                            break
                        if t2["id"] == t1["id"]:
                            continue
                        if job["skill"] not in t2["skills"]:
                            continue
                        seq2 = plan[t2["id"]]
                        c2_old = _rc(state, t2, seq2)
                        for pos in range(len(seq2) + 1):
                            new_seq2 = seq2[:pos] + [jid] + seq2[pos:]
                            c2_new = _rc(state, t2, new_seq2)
                            if c2_new == float('inf'):
                                continue
                            delta = (c1_new - c1_old) + (c2_new - c2_old)
                            delta += _churn_delta(state, jid, t1["id"], t2["id"])
                            if delta < -1e-9:
                                plan[t1["id"]] = new_seq1
                                plan[t2["id"]] = new_seq2
                                improved = True
                                done = True
                                break

        # 3. Swap jobs between techs
        if not improved:
            done = False
            for i1 in range(len(healthy)):
                if done:
                    break
                t1 = healthy[i1]
                seq1 = plan[t1["id"]]
                c1_old = _rc(state, t1, seq1)
                for i2 in range(i1 + 1, len(healthy)):
                    if done:
                        break
                    t2 = healthy[i2]
                    seq2 = plan[t2["id"]]
                    c2_old = _rc(state, t2, seq2)
                    for p1 in range(len(seq1)):
                        if done:
                            break
                        jid1 = seq1[p1]
                        job1 = state["jobs"][jid1]
                        if job1["skill"] not in t2["skills"]:
                            continue
                        for p2 in range(len(seq2)):
                            jid2 = seq2[p2]
                            job2 = state["jobs"][jid2]
                            if job2["skill"] not in t1["skills"]:
                                continue
                            new_seq1 = seq1[:p1] + [jid2] + seq1[p1 + 1:]
                            new_seq2 = seq2[:p2] + [jid1] + seq2[p2 + 1:]
                            c1_new = _rc(state, t1, new_seq1)
                            c2_new = _rc(state, t2, new_seq2)
                            if c1_new == float('inf') or c2_new == float('inf'):
                                continue
                            delta = (c1_new - c1_old) + (c2_new - c2_old)
                            delta += _churn_delta(state, jid1, t1["id"], t2["id"])
                            delta += _churn_delta(state, jid2, t2["id"], t1["id"])
                            if delta < -1e-9:
                                plan[t1["id"]] = new_seq1
                                plan[t2["id"]] = new_seq2
                                improved = True
                                done = True
                                break

        # 4. Insert unscheduled jobs (with drops)
        if not improved:
            assigned = set()
            for t in healthy:
                assigned.update(plan[t["id"]])
            unscheduled = [jid for jid in state["jobs"] if jid not in assigned]
            unscheduled.sort(key=lambda jid: (
                not state["jobs"][jid]["emergency"],
                -state["jobs"][jid]["priority"],
                state["jobs"][jid]["release"],
            ))
            for jid in unscheduled:
                job = state["jobs"][jid]
                is_em = job["emergency"]
                best = _try_insert_improved(state, plan, healthy, jid, allow_drop=True)
                if best is not None:
                    plan[best[0]] = best[1]
                    improved = True
                    break
                elif is_em:
                    for t in healthy:
                        if job["skill"] in t["skills"]:
                            seq = plan[t["id"]]
                            for new_seq in ([jid] + seq, seq + [jid]):
                                kept, _ = _drop_low_priority(state, t, new_seq, keep=jid)
                                if kept is not None and jid in kept:
                                    plan[t["id"]] = kept
                                    improved = True
                                    break
                            if improved:
                                break
                    if improved:
                        break

        # 5. Replace a scheduled job with an unscheduled job
        if not improved:
            assigned = set()
            for t in healthy:
                assigned.update(plan[t["id"]])
            unscheduled = [jid for jid in state["jobs"] if jid not in assigned]
            unscheduled.sort(key=lambda jid: (
                not state["jobs"][jid]["emergency"],
                -state["jobs"][jid]["priority"],
            ))
            for u in unscheduled:
                job_u = state["jobs"][u]
                p_u = job_u["priority"]
                is_em_u = job_u["emergency"]
                for t in healthy:
                    if job_u["skill"] not in t["skills"]:
                        continue
                    seq = plan[t["id"]]
                    c_old = _rc(state, t, seq)
                    for j in seq:
                        job_j = state["jobs"][j]
                        p_j = job_j["priority"]
                        if not is_em_u and p_u <= p_j:
                            continue
                        base = [x for x in seq if x != j]
                        best_c = float('inf')
                        best_seq = None
                        for pos in range(len(base) + 1):
                            cand = base[:pos] + [u] + base[pos:]
                            c = _rc(state, t, cand)
                            if c < best_c - 1e-9:
                                best_c = c
                                best_seq = cand
                        if best_seq is not None and best_c < 1e6:
                            d = best_c - c_old - 150 * p_u + 150 * p_j
                            d += _churn_delta(state, u, None, t["id"])
                            d += _churn_delta(state, j, t["id"], None)
                            if d < -1e-9:
                                plan[t["id"]] = best_seq
                                improved = True
                                break
                    if improved:
                        break
                if improved:
                    break

        # 6. Unschedule a non-emergency job if it saves cost
        if not improved:
            done = False
            for t in healthy:
                if done:
                    break
                seq = plan[t["id"]]
                c_old = _rc(state, t, seq)
                for i in range(len(seq)):
                    jid = seq[i]
                    job = state["jobs"][jid]
                    if job["emergency"]:
                        continue
                    new_seq = seq[:i] + seq[i + 1:]
                    c_new = _rc(state, t, new_seq)
                    if c_new == float('inf'):
                        continue
                    delta = c_new - c_old + 150 * job["priority"]
                    delta += _churn_delta(state, jid, t["id"], None)
                    if delta < -1e-9:
                        plan[t["id"]] = new_seq
                        improved = True
                        done = True
                        break

        if not improved:
            break

    # Final full re-optimization of each tech's sequence
    for t in healthy:
        seq = plan[t["id"]]
        if len(seq) < 2:
            continue
        c_old = _rc(state, t, seq)
        new = _optimize_seq(state, t, seq, rounds=3)
        c_new = _rc(state, t, new)
        if c_new < c_old - 1e-9:
            plan[t["id"]] = new

    return plan


def replan(state):
    _RC_CACHE.clear()
    plan = _greedy_initial(state)
    plan = _local_search(state, plan)
    return {t["id"]: plan.get(t["id"], []) for t in state["techs"] if not t["sick"]}
